from uuid import uuid4

from flask_login import login_required, current_user
from flask import render_template, redirect, flash

from app import app
from models import RegistrationCode, Session


def _require_admin():
    if not current_user.is_admin:
        flash("Not authorized", "error")
        return redirect("/home")
    return None


@app.route("/registration-codes", methods=["GET"])
@login_required
def registration_codes():
    if (r := _require_admin()):
        return r
    with Session() as session:
        codes = session.query(RegistrationCode).all()
    return render_template("registration_codes.html", registration_codes=codes)


@app.route("/registration-codes", methods=["POST"])
@login_required
def add_registration_codes():
    if (r := _require_admin()):
        return r
    code_str = str(uuid4())
    with Session() as session:
        session.add(RegistrationCode(code_str))
        session.commit()
    flash(f"Code added: {code_str}", "success")
    return redirect("/registration-codes")
