from flask import Blueprint, session, request, url_for, redirect
from urllib.parse import urlparse, urljoin

xss_protection = Blueprint('xss_protection', __name__)

def _safe_url(target):
    if not target:
        return False
    ref = urlparse(request.host_url)
    test = urlparse(urljoin(request.host_url, target))
    return test.scheme in ('http', 'https') and ref.netloc == test.netloc

@xss_protection.route('/', methods=['POST'])
def index():
    session['xss_protection_enabled'] = not session.get('xss_protection_enabled', False)
    next_url = request.form.get('next') or request.args.get('next')
    if not _safe_url(next_url):
        next_url = url_for('index')
    return redirect(next_url)
